add("koKR", "objective", {
[155]="데피아즈단의 비밀 은신처까지 데피아즈단 변절자를 호위해 가야 합니다. 데피아즈단의 변절자가 밴클리프와 그의 동료가 숨어 있는 곳까지 안내한 이후에 그라이언 스타우트맨틀에게 돌아가 그 위치를 알려야 합니다.",
[870]="통가 룬토템에게 발견한 내용을 보고해야 합니다.",
[1144]="수입업자 윌릭스를 호위해 가시덩굴 우리에서 나가야 합니다.",
[1149]="믿음이 있다면 버섯구름 봉우리가 내려다보이는 높은 곳에서 판자 아래로 뛰어내리십시오.",
[1273]="오그론과 함께 가서 리테를 심문한 다음 담쟁이 마을에 있는 크로그에게 돌아가야 합니다.",
[1448]="스톰윈드에 있는 브로한 캐스크벨리가 아탈학카르 신전을 찾아 달라고 부탁했습니다.",
[1651]="데피아즈단의 공격으로부터 대프니 스틸웰을 보호하십시오. 둘 중 하나라도 죽으면 실패하게 됩니다. 성공한 후에 대프니 스틸웰과 다시 대화해야 합니다.",
[1699]="주어진 시간 내에 레스밴 동굴의 첫번째 분기점까지 들어갔다가 요루스 발리브루에게로 되돌아와야 합니다. 죽어서 영혼이 빠져나가서는 안 됩니다.",
[1719]="싸움꾼 윌을 꺾고 격투의 섬에 있는 클라녹 맥클라우드과 대화하십시오.",
[1955]="보주의 악마를 물리치고 타베사와 대화하십시오.",
[2240]="밸로그의 일지를 읽고 비밀 석실을 조사한 후 발굴조사단장 스톰파이크에게 보고해야 합니다.",
[2904]="태엽장치 통로 입구까지 케르노비를 호위한 후 무법항에 있는 스쿠티에게 가서 보고해야 합니다.",
[2936]="데카의 서판을 읽고 마른나무껍질부족 거미 신의 이름을 알아낸 후, 가드린 장로에게 돌아가십시오.",
[2989]="줄의 제단 위를 확인한 후, 그리핀 조련사 탈론액스에게 돌아가십시오.",
[3525]="가시덩굴 구릉에 있는 가시멧돼지의 우상까지 벨리스트라즈를 호위해야 합니다. 우상을 진화하는 의식을 수행하는 동안 벨리스트라즈를 보호해야 합니다.",
[4121]="포로인 그랄크 로크럽을 호송해 불타는 평원을 지나고 검은바위 산을 넘어 이글거리는 협곡으로 가야 합니다. 반대편에서 렉스로트의 부하들이 기다리다가 그랄크 로크럽을 인계받도록 하겠다고 렉스로트가 말했던 것이 기억납니다. 또한 토륨 족쇄를 렉스로트에게 전해주어야 합니다.",
[4322]="치안대장 윈저가 자신의 장비를 되찾고 갇힌 동료들을 풀어 주는 것을 도와야 합니다. 성공하면 치안대장 맥스웰에게 돌아가십시오.",
[4771]="스칼로맨스의 스칼로맨스 강당 문에 여명의 계략을 놓아두고 벡투스를 처치한 후 베티나 비글징크에게 돌아가야 합니다.",
[4941]="오그리마의 스랄의 요새에 있는 아이트리그와 대화해야 합니다. 아이트리그의 얘기를 듣고 난 후에는 대족장 스랄과 상의해야 합니다.",
[5096]="펠스톤 농장과 달슨의 눈물 사이에 있는 붉은십자군의 야영지로 가서 지휘 막사를 파괴하십시오. 기지에 스컬지 깃발을 세운 후, 서부 역병지대의 보루에 있는 고위집행관 델링턴에게 돌아가야 합니다.",
[6403]="레지널드 윈저를 따라 스톰윈드를 통과해 왕궁으로 가야합니다. 윈저를 보호하십시오!",
[6566]="스랄의 이야기를 들어야 합니다.",
[6627]="브라우그 딤스피릿의 질문에 대한 정답을 맞춘 다음 그에게 다시 말을 걸어야 합니다. 준비가 될 때까지 브라우그 딤스피릿은 돌발톱 산맥에 있을 것입니다.",
[8115]="아라시 분지에서 동시에 다섯 곳의 거점을 점령하는 임무를 완수한 다음 임시 주둔지에 있는 야전사령관 오슬라이트에게 돌아가십시오.",
[8286]="타나리스에 있는 시간의 동굴로 가서 노즈도르무 혈족인 아나크로노스를 찾아야 합니다.",
[8519]="잊혀진 오랜 기억에 대해 가능한 모든 것을 확인한 후 타나리스의 시간의 동굴에 있는 아나크로노스와 대화하십시오.",
[9264]="썬더 블러프 바깥의 스컬지 요새 근처에서 빛나는 마법진을 조사해야 합니다. 그리고 스컬지를 처치하여 희미하게 빛나는 죽음의 돌 3개를 모아가야 합니다.",
[92401]="Level 22 로데론의 폐허에서 에드워드 하트위버의 실종에 관해 조사해야 합니다.",
})
